	zassert_not_null(p, "alloc failed");
	ops->free(p);
	ASSERT_VIOLATION(do_write(p, 0, 0xAA));

	uint8_t *q = ops->alloc(16);

	zassert_not_null(q, "re-alloc failed");
	for (int i = 0; i < 16; i++) {
		do_write(q, i, (uint8_t)i);
	}
	ops->free(q);
}

